import{_ as o,a0 as l,w as u,s as r,I as a,x as n,a1 as p,A as e,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Ubuntu Core：製作包含私有 snap 的工廠鏡像 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu Core：製作包含私有 snap 的工廠鏡像 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu Core：製作包含私有 snap 的工廠鏡像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu Core：製作包含私有 snap 的工廠鏡像 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170711 Ubuntu Core Making a factory image with private snaps","title":"Ubuntu Core：製作包含私有 snap 的工廠鏡像","tag":"201708","desc":""},"relativePath":"201708/20170711 Ubuntu Core Making a factory image with private snaps.md","filePath":"[post].md"}'),d={name:"201708/20170711 Ubuntu Core Making a factory image with private snaps.md"};function g(b,s,m,f,k,h){const t=l("Link");return u(),r("div",null,[s[33]||(s[33]=a("h1",{id:"ubuntu-core-製作包含私有-snap-的工廠鏡像",tabindex:"-1"},[n("Ubuntu Core：製作包含私有 snap 的工廠鏡像 "),a("a",{class:"header-anchor",href:"#ubuntu-core-製作包含私有-snap-的工廠鏡像","aria-label":"Permalink to “Ubuntu Core：製作包含私有 snap 的工廠鏡像”"},"​")],-1)),a("p",null,[s[1]||(s[1]=n("這篇帖子是有關 ",-1)),p(t,{href:"https://insights.ubuntu.com/2017/04/06/from-ros-prototype-to-production-on-ubuntu-core/"},{default:e(()=>[...s[0]||(s[0]=[n("在 Ubuntu Core 開發 ROS 原型到成品",-1)])]),_:1}),s[2]||(s[2]=n(" 系列的補充，用來回答我收到的一個問題： “我想做一個工廠鏡像，但我不想使我的 snap 公開” 當然，這個問題和回答都不只是針對於機器人技術。在這篇帖子中，我將會通過兩種方法來回答這個問題。",-1))]),a("p",null,[s[5]||(s[5]=n("開始之前，你需要了解一些製作 Ubuntu Core 鏡像的背景知識，如果你已經看過 [在 Ubuntu Core 開發 ROS 原型到成品",-1)),p(t,{href:"https://insights.ubuntu.com/2017/04/06/from-ros-prototype-to-production-on-ubuntu-core/"},{default:e(()=>[...s[3]||(s[3]=[n("3",-1)])]),_:1}),s[6]||(s[6]=n(" 系列文章（具體是第 5 部分），你就已經有了需要的背景知識，如果沒有看過的話，可以查看有關 ",-1)),p(t,{href:"https://tutorials.ubuntu.com/tutorial/create-your-own-core-image"},{default:e(()=>[...s[4]||(s[4]=[n("製作你的 Ubuntu Core 鏡像",-1)])]),_:1}),s[7]||(s[7]=n(" 的教程。",-1))]),s[34]||(s[34]=i(`<p>如果你已經瞭解了最新的情況，並且當我説 “模型定義” 或者 “模型斷言” 時知道我在談論什麼，那就讓我們開始通過不同的方法使用私有 sanps 來製作 Ubuntu Core 鏡像吧。</p><h3 id="方法-1-不要上傳你的-snap-到商店" tabindex="-1">方法 1： 不要上傳你的 snap 到商店 <a class="header-anchor" href="#方法-1-不要上傳你的-snap-到商店" aria-label="Permalink to “方法 1： 不要上傳你的 snap 到商店”">​</a></h3><p>這是最簡單的方法了。首先看一下這個有關模型定義的例子——<code>amd64-model.json</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;model&quot;,</span></span>
<span class="line"><span>    &quot;series&quot;: &quot;16&quot;,</span></span>
<span class="line"><span>    &quot;model&quot;: &quot;custom-amd64&quot;,</span></span>
<span class="line"><span>    &quot;architecture&quot;: &quot;amd64&quot;,</span></span>
<span class="line"><span>    &quot;gadget&quot;: &quot;pc&quot;,</span></span>
<span class="line"><span>    &quot;kernel&quot;: &quot;pc-kernel&quot;,</span></span>
<span class="line"><span>    &quot;authority-id&quot;: &quot;4tSgWHfAL1vm9l8mSiutBDKnnSQBv0c8&quot;,</span></span>
<span class="line"><span>    &quot;brand-id&quot;: &quot;4tSgWHfAL1vm9l8mSiutBDKnnSQBv0c8&quot;,</span></span>
<span class="line"><span>    &quot;timestamp&quot;: &quot;2017-06-23T21:03:24+00:00&quot;,</span></span>
<span class="line"><span>    &quot;required-snaps&quot;: [&quot;kyrofa-test-snap&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>讓我們將它轉換成模型斷言：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat amd64-model.json | snap sign -k my-key-name &gt; amd64.model</span></span>
<span class="line"><span>You need a passphrase to unlock the secret key for</span></span>
<span class="line"><span>user: &quot;my-key-name&quot;</span></span>
<span class="line"><span>4096-bit RSA key, ID 0B79B865, created 2016-01-01</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>獲得模型斷言：<code>amd64.model</code> 後，如果你現在就把它交給 <code>ubuntu-image</code> 使用，你將會碰釘子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ubuntu-image -c stable amd64.model </span></span>
<span class="line"><span>Fetching core</span></span>
<span class="line"><span>Fetching pc-kernel</span></span>
<span class="line"><span>Fetching pc</span></span>
<span class="line"><span>Fetching kyrofa-test-snap</span></span>
<span class="line"><span>error: cannot find snap &quot;kyrofa-test-snap&quot;: snap not found</span></span>
<span class="line"><span>COMMAND FAILED: snap prepare-image --channel=stable amd64.model /tmp/tmp6p453gk9/unpack</span></span></code></pre></div><p>實際上商店中並沒有名為 <code>kyrofa-test-snap</code> 的 snap。這裏需要重點説明的是：模型定義（以及轉換後的斷言）只包含了一系列的 snap 的名字。如果你在本地有個那個名字的 snap，即使它沒有存在於商店中，你也可以通過 <code>--extra-snaps</code> 選項告訴 <code>ubuntu-image</code> 在斷言中匹配這個名字來使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ubuntu-image -c stable \\</span></span>
<span class="line"><span>         --extra-snaps /path/to/kyrofa-test-snap_0.1_amd64.snap \\</span></span>
<span class="line"><span>         amd64.model</span></span>
<span class="line"><span>Fetching core</span></span>
<span class="line"><span>Fetching pc-kernel</span></span>
<span class="line"><span>Fetching pc</span></span>
<span class="line"><span>Copying &quot;/path/to/kyrofa-test-snap_0.1_amd64.snap&quot; (kyrofa-test-snap)</span></span>
<span class="line"><span>kyrofa-test-snap already prepared, skipping</span></span>
<span class="line"><span>WARNING: &quot;kyrofa-test-snap&quot; were installed from local snaps</span></span>
<span class="line"><span>disconnected from a store and cannot be refreshed subsequently!</span></span>
<span class="line"><span>Partition size/offset need to be a multiple of sector size (512).</span></span>
<span class="line"><span>The size/offset will be rounded up to the nearest sector.</span></span></code></pre></div><p>現在，在 snap 並沒有上傳到商店的情況下，你已經獲得一個預裝了私有 snap 的 Ubuntu Core 鏡像（名為 <code>pc.img</code>）。但是這樣做有一個很大的問題，ubuntu-image 會提示一個警告：不通過連接商店預裝 snap 意味着你沒有辦法在燒錄了這些鏡像的設備上更新它。你只能通過製作新的鏡像並重新燒錄到設備的方式來更新它。</p><h3 id="方法-2-使用品牌商店" tabindex="-1">方法 2： 使用品牌商店 <a class="header-anchor" href="#方法-2-使用品牌商店" aria-label="Permalink to “方法 2： 使用品牌商店”">​</a></h3>`,12)),a("p",null,[s[10]||(s[10]=n("當你註冊了一個商店賬號並訪問 ",-1)),p(t,{href:"https://dashboard.snapcraft.io/dev/snaps/"},{default:e(()=>[...s[8]||(s[8]=[n("dashboard.snapcraft.io",-1)])]),_:1}),s[11]||(s[11]=n(" 時，你其實是在標準的 Ubuntu 商店中查看你的 snap。如果你是在系統中新安裝的 snapd，默認會從這個商店下載。雖然你可以在 Ubuntu 商店中發佈私有的 snap，但是你",-1)),p(t,{href:"https://forum.snapcraft.io/t/unable-to-create-an-image-that-uses-private-snaps"},{default:e(()=>[...s[9]||(s[9]=[n("不能將它們預裝到鏡像中",-1)])]),_:1}),s[12]||(s[12]=n("，因為只有你（以及你添加的合作者）才有權限去使用它。在這種情況下製作鏡像的唯一方式就是公開發布你的 snap，然而這並不符合這篇帖子的目的。",-1))]),a("p",null,[s[14]||(s[14]=n("對於這種用例，我們有所謂的 ",-1)),p(t,{href:"https://docs.ubuntu.com/core/en/build-store/index?_ga=2.103787520.1269328701.1501772209-778441655.1499262639"},{default:e(()=>[...s[13]||(s[13]=[n("品牌商店",-1)])]),_:1}),s[15]||(s[15]=n("。品牌商店仍然託管在 Ubuntu 商店裏，但是它們是針對於某一特定公司或設備的一個定製的、專門的版本。品牌商店可以繼承或者不繼承標準的 Ubuntu 商店，品牌商店也可以選擇開放給所有的開發者或者將其限制在一個特定的組內（保持私有正是我們想要的）。",-1))]),a("p",null,[s[17]||(s[17]=n("請注意，這是一個付費功能。你需要 ",-1)),p(t,{href:"https://docs.ubuntu.com/core/en/build-store/create"},{default:e(()=>[...s[16]||(s[16]=[n("申請一個品牌商店",-1)])]),_:1}),s[18]||(s[18]=n("。請求通過後，你將可以通過訪問用户名下的 “stores you can access” 看到你的新商店。",-1))]),s[35]||(s[35]=i(`<p><img src="https://insights.ubuntu.com/wp-content/uploads/1a62/stores_you_can_access.jpg" alt=""></p><p>在那裏你可以看到多個有權使用的商店。最少的情況下也會有兩個：標準的 Ubuntu 商店以及你的新的品牌商店。選擇品牌商店（紅框），進去後記錄下你的商店 ID（藍框）：等下你將會用到它。</p><p><img src="https://insights.ubuntu.com/wp-content/uploads/b10c/Screenshot-from-2017-07-06-15-16-32.png" alt=""></p><p>在品牌商店裏註冊名字或者上傳 snap 和標準的商店使用的方法是一樣的，只是它們現在是上傳到你的品牌商店而不是標準的那個。如果你將品牌商店放在 unlisted 裏面，那麼這些 snap 對外部用户是不可見。但是這裏需要注意的是第一次上傳 snap 的時候需要通過 web 界面來操作。在那之後，你可以繼續像往常一樣使用 Snapcraft 來操作。</p><p>那麼這些是如何改變的呢？我的 “kyrofal-store” 從 Ubuntu 商店繼承了 snap，並且還包含一個發佈在穩定通道中的 “kyrofa-bran-test-snap” 。這個 snap 在 Ubuntu 商店裏是使用不了的，如果你去搜索它，你是找不到的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ snap find kyrofa-branded</span></span>
<span class="line"><span>The search &quot;kyrofa-branded&quot; returned 0 snaps</span></span></code></pre></div><p>但是使用我們前面記錄的商店 ID，我們可以創建一個從品牌商店而不是 Ubuntu 商店下載 snap 的模型斷言。我們只需要將 “store” 鍵添加到 JSON 文件中，就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;model&quot;,</span></span>
<span class="line"><span>    &quot;series&quot;: &quot;16&quot;,</span></span>
<span class="line"><span>    &quot;model&quot;: &quot;custom-amd64&quot;,</span></span>
<span class="line"><span>    &quot;architecture&quot;: &quot;amd64&quot;,</span></span>
<span class="line"><span>    &quot;gadget&quot;: &quot;pc&quot;,</span></span>
<span class="line"><span>    &quot;kernel&quot;: &quot;pc-kernel&quot;,</span></span>
<span class="line"><span>    &quot;authority-id&quot;: &quot;4tSgWHfAL1vm9l8mSiutBDKnnSQBv0c8&quot;,</span></span>
<span class="line"><span>    &quot;brand-id&quot;: &quot;4tSgWHfAL1vm9l8mSiutBDKnnSQBv0c8&quot;,</span></span>
<span class="line"><span>    &quot;timestamp&quot;: &quot;2017-06-23T21:03:24+00:00&quot;,</span></span>
<span class="line"><span>    &quot;required-snaps&quot;: [&quot;kyrofa-branded-test-snap&quot;],</span></span>
<span class="line"><span>    &quot;store&quot;: &quot;ky&lt;secret&gt;ek&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用方法 1 中的方式對它簽名，然後我們就可以像這樣很簡單的製作一個預裝有我們品牌商店私有 snap 的 Ubuntu Core 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ubuntu-image -c stable amd64.model</span></span>
<span class="line"><span>Fetching core</span></span>
<span class="line"><span>Fetching pc-kernel</span></span>
<span class="line"><span>Fetching pc</span></span>
<span class="line"><span>Fetching kyrofa-branded-test-snap</span></span>
<span class="line"><span>Partition size/offset need to be a multiple of sector size (512).</span></span>
<span class="line"><span>The size/offset will be rounded up to the nearest sector.</span></span></code></pre></div><p>現在，和方法 1 的最後一樣，你獲得了一個為工廠準備的 <code>pc.img</code>。並且使用這種方法制作的鏡像中的所有 snap 都從商店下載的，這意味着它們將能像平常一樣自動更新。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3>`,12)),a("p",null,[s[20]||(s[20]=n("到目前為止，做這個只有兩種方法。當我開始寫這篇帖子的時候，我想過可能還有第三種（將 snap 設置為私有然後使用它製作鏡像），",-1)),p(t,{href:"https://forum.snapcraft.io/t/unable-to-create-an-image-that-uses-private-snaps/1115"},{default:e(()=>[...s[19]||(s[19]=[n("但最後證明是不行的",-1)])]),_:1}),s[21]||(s[21]=n("。",-1))]),s[36]||(s[36]=a("p",null,"另外，我們也收到很多內部部署或者企業商店的請求，雖然這樣的產品還沒有公佈，但是商店團隊正在從事這項工作。一旦可用，我將會寫一篇有關它的文章。",-1)),s[37]||(s[37]=a("p",null,"希望能幫助到您！",-1)),s[38]||(s[38]=a("hr",null,null,-1)),s[39]||(s[39]=a("p",null,"關於作者",-1)),s[40]||(s[40]=a("p",null,"Kyle 是 Snapcraft 團隊的一員，也是 Canonical 公司的常駐機器人專家，他專注於 snaps 和 snap 開發實踐，以及 snaps 和 Ubuntu Core 的機器人技術實現。",-1)),s[41]||(s[41]=a("hr",null,null,-1)),a("p",null,[s[23]||(s[23]=n("via: ",-1)),p(t,{href:"https://insights.ubuntu.com/2017/07/11/ubuntu-core-making-a-factory-image-with-private-snaps/"},{default:e(()=>[...s[22]||(s[22]=[n("https://insights.ubuntu.com/2017/07/11/ubuntu-core-making-a-factory-image-with-private-snaps/",-1)])]),_:1})]),a("p",null,[s[26]||(s[26]=n("作者：[Kyle Fazzari][a] 譯者：",-1)),p(t,{href:"https://github.com/Snaplee"},{default:e(()=>[...s[24]||(s[24]=[n("Snaplee",-1)])]),_:1}),s[27]||(s[27]=n(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[25]||(s[25]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[30]||(s[30]=n("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原創編譯，",-1)),p(t,{href:"https://linux.cn/"},{default:e(()=>[...s[29]||(s[29]=[n("Linux中國",-1)])]),_:1}),s[32]||(s[32]=n(" 榮譽推出",-1))])])}const C=o(d,[["render",g]]);export{y as __pageData,C as default};
